Gif_Stream* read_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler("Memory allocation for GIF stream failed.", landmark);
        return NULL;
    }

    // Validate GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler("Invalid GIF signature.", landmark);
        free(stream);
        return NULL;
    }

    // Initialize stream
    stream->images = NULL;
    stream->image_count = 0;
    stream->extensions = NULL;
    stream->extension_count = 0;

    // Process image blocks
    while (grr->position < grr->length) {
        char block_type = grr->data[grr->position++];

        if (block_type == 0x2C) {
            // Image block
            if (!process_gif_image(grr, stream, read_flags, handler)) {
                cleanup_gif_stream(stream);
                return NULL;
            }
        } else if (block_type == 0x21) {
            // Extension block
            if (!process_gif_extension(grr, stream, read_flags, handler)) {
                cleanup_gif_stream(stream);
                return NULL;
            }
        } else if (block_type == 0x3B) {
            // GIF terminator
            break;
        } else {
            handler("Unknown GIF block type.", landmark);
            cleanup_gif_stream(stream);
            return NULL;
        }
    }

    if (stream->image_count == 0) {
        handler("No images found in GIF stream.", landmark);
        cleanup_gif_stream(stream);
        return NULL;
    }

    return stream;
}
